import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"19、【臨】 兌下坤上","description":"溫公易說 - 19、【臨】 兌下坤上","frontmatter":{"title":"19、【臨】 兌下坤上","description":"溫公易說 - 19、【臨】 兌下坤上"},"headers":[],"relativePath":"classics/wengong/020.md","filePath":"classics/wengong/020.md"}'),l={name:"classics/wengong/020.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_19、【臨】-兌下坤上" tabindex="-1">19、【臨】 兌下坤上 <a class="header-anchor" href="#_19、【臨】-兌下坤上" aria-label="Permalink to “19、【臨】 兌下坤上”">​</a></h1><h3 id="彖曰-臨-剛浸而長-說而順-剛中而應-大亨以正-天之道也。至於八月有兇-消不久也。" tabindex="-1">彖曰：臨，剛浸而長，說而順，剛中而應，大亨以正，天之道也。至於八月有兇，消不久也。 <a class="header-anchor" href="#彖曰-臨-剛浸而長-說而順-剛中而應-大亨以正-天之道也。至於八月有兇-消不久也。" aria-label="Permalink to “彖曰：臨，剛浸而長，說而順，剛中而應，大亨以正，天之道也。至於八月有兇，消不久也。”">​</a></h3><p>八月者，周之八月也。陽生於復，長於臨，陰生於姤，長於遁。遁與臨反者也。聖人防微杜漸，故於陽長之初，而著陰之戒也。</p><h3 id="象曰-澤上有地-臨。君子以教思無窮-容保民無疆。" tabindex="-1">象曰：澤上有地，臨。君子以教思無窮，容保民無疆。 <a class="header-anchor" href="#象曰-澤上有地-臨。君子以教思無窮-容保民無疆。" aria-label="Permalink to “象曰：澤上有地，臨。君子以教思無窮，容保民無疆。”">​</a></h3><p>教思無窮，容保民無疆，功之所以大也。</p><h3 id="初九-鹹臨-貞吉-象曰-鹹臨-貞吉-志行正也。" tabindex="-1">初九：鹹臨，貞吉 象曰：鹹臨，貞吉，志行正也。 <a class="header-anchor" href="#初九-鹹臨-貞吉-象曰-鹹臨-貞吉-志行正也。" aria-label="Permalink to “初九：鹹臨，貞吉 象曰：鹹臨，貞吉，志行正也。”">​</a></h3><p>君子之所以能自大者，學於道也。學充於內，則志氣夷懌矣。浸長於外，則人化而順之矣。人化而順之所以大也，有應於外，化順之象也。夫道以正心為本，初九所以能感物而大，志行正也。孔子曰：學而時習之，不亦悅乎？有朋自遠方來，不亦樂乎？傳曰：大學之本，心正然後身修。</p><h3 id="九二-鹹臨-吉-無不利-象曰-鹹臨-吉無不利-未順命也。" tabindex="-1">九二：鹹臨，吉，無不利 象曰：鹹臨，吉無不利，未順命也。 <a class="header-anchor" href="#九二-鹹臨-吉-無不利-象曰-鹹臨-吉無不利-未順命也。" aria-label="Permalink to “九二：鹹臨，吉，無不利 象曰：鹹臨，吉無不利，未順命也。”">​</a></h3><p>二在下體而不當位，故小人未肯盡受命也。</p><h3 id="六三-甘臨-無攸利-既憂之-無咎-象曰-甘臨-位不當也。既憂之-咎不長也。" tabindex="-1">六三：甘臨，無攸利，既憂之，無咎 象曰：甘臨，位不當也。既憂之，咎不長也。 <a class="header-anchor" href="#六三-甘臨-無攸利-既憂之-無咎-象曰-甘臨-位不當也。既憂之-咎不長也。" aria-label="Permalink to “六三：甘臨，無攸利，既憂之，無咎 象曰：甘臨，位不當也。既憂之，咎不長也。”">​</a></h3><h3 id="六四-至臨-無咎-象曰-至臨-無咎-位當也。" tabindex="-1">六四：至臨，無咎 象曰：至臨，無咎，位當也。 <a class="header-anchor" href="#六四-至臨-無咎-象曰-至臨-無咎-位當也。" aria-label="Permalink to “六四：至臨，無咎 象曰：至臨，無咎，位當也。”">​</a></h3><p>進升上體，至大之境，已得其位，故無咎也。</p><h3 id="六五-知臨-大君之宜-吉-象曰-大君之宜-行中之謂也。" tabindex="-1">六五：知臨，大君之宜，吉 象曰：大君之宜，行中之謂也。 <a class="header-anchor" href="#六五-知臨-大君之宜-吉-象曰-大君之宜-行中之謂也。" aria-label="Permalink to “六五：知臨，大君之宜，吉 象曰：大君之宜，行中之謂也。”">​</a></h3><h3 id="上六-敦臨-吉-無咎-象曰-敦臨之吉-志在內也。" tabindex="-1">上六：敦臨，吉，無咎 象曰：敦臨之吉，志在內也。 <a class="header-anchor" href="#上六-敦臨-吉-無咎-象曰-敦臨之吉-志在內也。" aria-label="Permalink to “上六：敦臨，吉，無咎 象曰：敦臨之吉，志在內也。”">​</a></h3>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
